    currency_id smallint NOT NULL,
    grp_exchange numeric(16,4),
    org_exchange numeric(16,4),
    gross_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    goods_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    services_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    charges_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    shipping_amount numeric(16,2) DEFAULT '0'::numeric,
    insurance_amount numeric(16,2) DEFAULT '0'::numeric,
    net_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    grp_net_amount numeric(16,2),
    org_net_amount numeric(16,2),
    tax_category_id smallint NOT NULL,
    tax_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    total_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    payment_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    data jsonb NOT NULL,
    fetched_at timestamp(0) with time zone,
    last_fetched_at timestamp(0) with time zone,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    deleted_at timestamp(0) with time zone,
    source_id character varying(255),
    is_vip boolean DEFAULT false NOT NULL,
    as_organisation_id smallint,
    as_employee_id smallint,
    platform_id integer,
    pay_status character varying(255),
    updated_by_customer_at timestamp(0) with time zone,
    shipping_engine character varying(255) DEFAULT 'auto'::character varying NOT NULL,
    charges_engine character varying(255) DEFAULT 'auto'::character varying NOT NULL,
    customer_sales_channel_id bigint,
    platform_order_id character varying(255),
    shipping_notes text,
    traffic_sources text,
    master_shop_id smallint,
    pay_detailed_status character varying(255),
    is_premium_dispatch boolean DEFAULT false NOT NULL,
    has_extra_packing boolean,
    post_submit_modification_data jsonb,
    shipping_zone_schema_id smallint,
    shipping_zone_id smallint,
    to_be_paid_by character varying(255),
    has_insurance boolean,
    is_re boolean DEFAULT false NOT NULL,
    offer_meters jsonb DEFAULT '{}'::jsonb,
    is_shipping_tbc boolean DEFAULT false NOT NULL,
    shipping_tbc_amount numeric(16,2),
    external_id character varying(255),
    tracking_number character varying(255),
    shipping_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    categories_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    with_replacement boolean DEFAULT false NOT NULL,
    discretionary_offers_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    marketplace_id character varying(255),
    commission_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    profit_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    margin numeric(10,4),
    is_shipping_by_external boolean DEFAULT false NOT NULL,
    picked_at timestamp(0) with time zone,
    packing_at timestamp(0) with time zone,
    amount_off numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    handling_blocked_at timestamp(0) with time zone,
    email character varying(255),
    phone character varying(255),
    contact_name character varying(256),
    company_name character varying(256),
    offer_voucher_id integer,
    discounted_shipping_offer_id integer,
    is_pastpay boolean DEFAULT false NOT NULL,
    is_bypass_platform_update boolean DEFAULT false NOT NULL
);


