--

CREATE TABLE public.organisations (
    id smallint NOT NULL,
    group_id smallint NOT NULL,
    ulid character(26) NOT NULL,
    type character varying(255) NOT NULL,
    slug character varying(255) NOT NULL COLLATE public.und_ns,
    code character varying(255) NOT NULL,
    name character varying(255) NOT NULL,
    contact_name character varying(255),
    email character varying(255),
    phone character varying(255),
    status boolean DEFAULT true NOT NULL,
    address_id integer,
    location jsonb NOT NULL,
    data jsonb NOT NULL,
    settings jsonb NOT NULL,
    source jsonb NOT NULL,
    country_id smallint NOT NULL,
    language_id smallint NOT NULL,
    timezone_id smallint NOT NULL,
    currency_id smallint NOT NULL,
    image_id integer,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    fetched_at timestamp(0) with time zone,
    last_fetched_at timestamp(0) with time zone,
    deleted_at timestamp(0) with time zone,
    source_id character varying(255),
    colour character varying(255),
    forbidden_dispatch_countries jsonb,
    opening_hours json DEFAULT '{}'::json NOT NULL,
    late_grace_period_minutes integer DEFAULT 15 NOT NULL,
    banned_country_regions jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_aiku_stock_control boolean DEFAULT false NOT NULL,
    is_aiku_stock_hr boolean DEFAULT false NOT NULL,
    is_aiku_stock_procurement boolean DEFAULT false NOT NULL,
    is_aiku_stock_production boolean DEFAULT false NOT NULL
);


