--
-- Name: transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transactions (
    id bigint NOT NULL,
    group_id smallint NOT NULL,
    organisation_id smallint NOT NULL,
    shop_id smallint NOT NULL,
    customer_id integer NOT NULL,
    customer_client_id integer,
    order_id integer,
    invoice_id integer,
    date timestamp(0) with time zone NOT NULL,
    submitted_at timestamp(0) with time zone,
    in_warehouse_at timestamp(0) with time zone,
    settled_at timestamp(0) with time zone,
    state character varying(255) DEFAULT '1'::character varying NOT NULL,
    status character varying(255) DEFAULT '1'::character varying NOT NULL,
    model_type character varying(255),
    model_id integer,
    asset_id integer,
    historic_asset_id integer,
    quantity_ordered numeric(16,6),
    quantity_bonus numeric(16,6) DEFAULT '0'::numeric,
    quantity_dispatched numeric(16,6) DEFAULT '0'::numeric,
    quantity_fail numeric(16,6) DEFAULT '0'::numeric,
    quantity_cancelled numeric(16,6) DEFAULT '0'::numeric,
    out_of_stock_in_basket boolean DEFAULT false NOT NULL,
    out_of_stock_in_basket_at timestamp(0) with time zone,
    fail_status character varying(255),
    gross_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    net_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    grp_net_amount numeric(16,2),
    org_net_amount numeric(16,2),
    tax_category_id smallint NOT NULL,
    grp_exchange numeric(16,4),
    org_exchange numeric(16,4),
    data jsonb NOT NULL,
    created_at timestamp(0) with time zone,
    updated_at timestamp(0) with time zone,
    fetched_at timestamp(0) with time zone,
    last_fetched_at timestamp(0) with time zone,
    deleted_at timestamp(0) with time zone,
    source_id character varying(255),
    source_alt_id character varying(255),
    estimated_weight integer,
    platform_transaction_id character varying(255),
    quantity_picked numeric(16,6),
    submitted_quantity_ordered numeric(16,6) DEFAULT '0'::numeric NOT NULL,
    offers_data json DEFAULT '{}'::json,
    dispatched_at timestamp(0) with time zone,
    cancelled_at timestamp(0) with time zone,
    family_id integer,
    department_id integer,
    sub_department_id integer,
    discretionary_offer numeric(6,3),
    discretionary_offer_label character varying(255),
    label character varying(255),
    marketplace_id character varying(255),
    is_cut_view boolean DEFAULT false NOT NULL,
    commission_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    profit_amount numeric(16,2) DEFAULT '0'::numeric NOT NULL,
    margin numeric(10,4),
    is_gift boolean DEFAULT false NOT NULL,
    submitted_gross_amount numeric(16,2),
    submitted_net_amount numeric(16,2),
    submitted_discount_factor double precision DEFAULT '1'::double precision NOT NULL,
    current_discount_factor double precision DEFAULT '1'::double precision NOT NULL,
    submitted_offers_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    has_discount_when_submitted boolean DEFAULT false NOT NULL,
    is_follow_on boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN transactions.gross_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transactions.gross_amount IS 'net amount before discounts';


--
-- Name: COLUMN transactions.source_alt_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transactions.source_alt_id IS 'to be used in no products transactions';


--
-- Name: COLUMN transactions.estimated_weight; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transactions.estimated_weight IS 'grams';


